window.AUTH=window.AUTH||{};window.AUTH["21-476"]={"d":"21-476","id":"2022/21-476","n":"303 Creative LLC v. Elenis","briefs":[{"k":"petitioner","label":"Brief of petitioners 303 Creative LLC, et al.","date":"2022-05-26","url":"https://www.supremecourt.gov/DocketPDF/21/21-476/226347/20220526141015058_21-476%20Brief%20for%20Petitioner.pdf","side":"pet","n":75},{"k":"respondent","label":"Brief of respondents Aubrey Elenis, et al.","date":"2022-08-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-476/233350/20220812133015020_21-476%20Brief%20for%20Respondents%20Final.pdf","side":"res","n":55},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-08-19","url":"https://www.supremecourt.gov/DocketPDF/21/21-476/234119/20220819182151542_21-476%20303%20Creative%20LLC%20v.%20Elenis%20FINAL.pdf","side":"us","n":34},{"k":"reply","label":"Reply of petitioners 303 Creative LLC, et al.","date":"2022-09-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-476/237603/20220912112429290_21-476%20Merits%20Reply%20Brief.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/600us1r58_7khn.pdf","tr":true,"items":[{"t":"case","label":"Abood v. Detroit Board of Education","cite":"431 U.S. 209","y":1977,"id":"1976/75-1153","sc":1,"sum":"A Michigan statute authorizing union representation of local governmental employees permits an \"agency shop\" arrangement, whereby every employee represented by a union, even though not a union member, must pay to the union, as a condition of employment, a service charge equal in amount to union dues. Appellant teachers filed actions (later consolidated) m Michigan state court against appellee Detroit Board of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","3":"21"}},{"t":"case","label":"Arizona Free Enterprise Club’s Freedom Club PAC v. Bennett","cite":"564 U.S. 721","y":2011,"id":"2010/10-238","sc":1,"op":1,"sum":"The Court held that the Arizona campaign finance law linking public financing for candidates to the amount spent by their opponents violated the First Amendment's protection of political speech.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Ashcroft v. ACLU","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Ashcroft v. Free Speech Coalition","cite":"535 U.S. 234","y":2002,"id":"2001/00-795","sc":1,"sum":"The Court held that the two prohibitions described above are overbroad and unconstitutional. The Court found the CPPA to be inconsistent with Miller insofar as the CPPA cannot be read to prohibit obscenity, because it lacks the required link between its prohibitions and the affront to community standards prohibited by the obscenity definition.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Associated Press v. United States","cite":"326 U.S. 1","y":1945,"id":"1940-1955/326us1","sc":1,"sum":"in gathering and distributing news in interstate and foreign commerce, prohibited service of AP news to non-members, prohibited members from furnishing spontaneous news to non-members, and empowered members to block membership applications of competitors. A contract between AP and a Canadian press association obligated both to furnish news exclusively to each other. Charging inter clia that the by-laws and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Barr v. American Association of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Boos v. Barry","cite":"485 U.S. 312","y":1988,"id":"1987/86-803","sc":1,"sum":"The Court found that the Code's restriction on sign displays violated the First Amendment while the ban on congregations did not. First, Justice O'Connor argued that the prohibition on signs failed to meet the high standards that the Court uses when evaluating the content-based regulation of political speech in a public forum.","sumSrc":"Oyez","by":{"0":"39, 40"}},{"t":"case","label":"Boy Scouts of America v. Dale","cite":"530 U.S. 640","y":2000,"id":"1999/99-699","sc":1,"op":14,"sum":"Reasoning that Dale was excluded for being a gay rights activist, not for being gay.","sumSrc":"opinion","by":{"0":"18, 21, 37","1":"17, 18","2":"6, 13, 14, 15, 16, 23","3":"17, 18, 22"}},{"t":"case","label":"Brown v. Entertainment Merchants Association","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"op":2,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"41","3":"14, 20"}},{"t":"case","label":"Brush & Nib Studio, LC v. City of Phoenix","cite":"448 P.3d 890","y":2019,"court":"Ariz.","url":"https://www.courtlistener.com/c/P.3d/448/890/","by":{"0":"48"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"32, 40"}},{"t":"case","label":"Burson v. Freeman","cite":"504 U.S. 191","y":1992,"id":"1991/90-1056","sc":1,"sum":"After subjecting Tennessee's statute to exacting scrutiny, since it constituted a facial content-based restriction on political speech in a public forum, the Court held that the statute was narrowly drafted to serve a compelling state interest. By creating a safe zone around polling sites, the statute served the state's interest in protecting its citizen's right to vote freely and effectively.","sumSrc":"Oyez","by":{"0":"36","1":"36"}},{"t":"case","label":"Cantwell v. Connecticut","cite":"310 U.S. 296","y":1940,"id":"1940-1955/310us296","sc":1,"sum":"The Court found that it was a violation of the First Amendment to restrict solicitation of religious speech.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"City of Lakewood v. Plain Dealer Publishing Company","cite":"486 U.S. 750","y":1988,"id":"1987/86-1042","sc":1,"sum":"The Court held that the licensing ordinance was facially invalid since it gave Lakewood's mayor unbridled discretion to discriminate against permit seekers, based on the content of their publications and viewpoints. This, in turn, promoted self-censorship by publishers and other speakers who sought to curry favor with the mayor's officer in order to secure the approval of their licensing requests.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Cohen v. California","cite":"403 U.S. 15","y":1971,"id":"1970/299","sc":1,"sum":"The Court ruled that a California statute prohibiting the display of offensive messages such as \"F--- the Draft\" violated freedom of expression as protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"2, 3, 16, 39","3":"17"}},{"t":"case","label":"Colorado Republican Federal Campaign Committee v. FEC","cite":"518 U.S. 604","y":1996,"id":"1995/95-489","sc":1,"sum":"Justice Stephen G. Breyer announced the judgment of the Court and authored an opinion, in which the Court ruled that the First Amendment prohibits the application of the Party Expenditure Provision of the Federal Election Campaign Act of 1971 (FECA) to the kind of expenditure at issue here-an expenditure that the political party has made independently, without coordination with any candidate.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Consolidated Edison Company of New York, Inc. v. Public Service Commission of New York","cite":"447 U.S. 530","y":1980,"id":"1979/79-134","sc":1,"sum":"An order of appellee New York Public Service Commission that prohibits the inclusion by appellant (and other public utility companies) in monthly bills of inserts discussing controversial issues of public policy directly infringes the freedom of speech protected by the First and Fourteenth Amendments and thus is invalid. Cf. First National Bank of Boston v. Bellotti, 435 U. S. 765.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 46","3":"20"}},{"t":"case","label":"Coral Ridge Ministries Media, Inc. v. Amazon.com, Inc.","cite":"6 F.4th 1247","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/1247/","op":14,"by":{"0":"48"}},{"t":"case","label":"Denver Area Education Telecommunications Consortium, Inc. v. FCC","cite":"518 U.S. 727","y":1996,"id":"1995/95-124","sc":1,"sum":"In a 6-to-3 decision, The Court held that the Act's grant of authority to leased channel cable operators under 10(a) - allowing them to restrict the transmission of \"patently offensive\" or indecent programming - is consistent with the First Amendment.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Expressions Hair Design v. Schneiderman","cite":"137 S. Ct. 1144","y":2017,"id":"2016/15-1391","sc":1,"sum":"The Court decided that the New York General Business Law’s was not unconstitutionally vague under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"F.C.C. v. Pacifica Foundation","cite":"438 U.S. 726","y":1978,"id":"1977/77-528","sc":1,"sum":"The Court held that audience, medium, time of day and method of transmission were all relevant factors in determining what speech is protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"FEC v. Cruz, __ S. Ct. __","cite":"2022 WL 1528348","y":2022,"court":"U.S. May 16","by":{"0":"38"}},{"t":"case","label":"First National Bank of Boston v. Bellotti","cite":"435 U.S. 765","y":1978,"id":"1977/76-1172","sc":1,"op":70,"ar":17,"sum":"The Court held that the right to attempt to influence the outcomes of elections is one of the primary rights the First Amendment was meant to protect. If this form of speech came from a person rather than a corporation, there would be no question about whether it was protected speech.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"141 S. Ct. 1868","y":2021,"id":"2020/19-123","sc":1,"ar":6,"sum":"Philadelphia’s refusal to contract with Catholic Social Services for the provision of foster care services unless CSS agrees to certify same-sex couples as foster parents violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37, 38, 42, 49","1":"8, 27, 30, 32","2":"32, 33","3":"18, 19"}},{"t":"case","label":"Global Discount Travel Services, LLC v. Trans World Airlines, Inc.","cite":"960 F. Supp. 701","y":1997,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./960/701/","by":{"0":"45"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"ar":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"25, 36","2":"29","3":"7, 17"}},{"t":"case","label":"Hurley v. Irish–American Gay, Lesbian and Bisexual Group of Boston","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"op":30,"ar":18,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"0":"passim","1":"17, 19, 29","2":"passim","3":"passim"}},{"t":"case","label":"Hustler Magazine, Inc. v. Falwell","cite":"485 U.S. 46","y":1988,"id":"1987/86-1278","sc":1,"sum":"The Court ruled that the First Amendment's freedom of speech protection extended to the making of clearly offensive statements about public figures, so long as such speech could not reasonably be construed to convey facts about its subject.","sumSrc":"Oyez","by":{"0":"25, 31, 35"}},{"t":"case","label":"Iancu v. Brunetti","cite":"139 S. Ct. 2294","y":2019,"id":"2018/18-302","sc":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"31"}},{"t":"case","label":"Irish-American Gay, Lesbian & Bisexual Group of Boston v. City of Boston","cite":"636 N.E.2d 1293","y":1994,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/636/1293/","op":4,"by":{"0":"26"}},{"t":"case","label":"Janus v. American Federation of State, County, & Municipal Employees, Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"op":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"0":"14, 16, 39","3":"12"}},{"t":"case","label":"Kaplan v. California","cite":"413 U.S. 115","y":1973,"id":"1972/71-1422","sc":1,"op":2,"sum":"Petitioner, a proprietor of an \"adult\" bookstore, was convicted of violating a California obscenity statute by selling a plain-covered unillustrated book containing repetitively descriptive material of an explicitly sexual nature. Both sides offered testimony as to the nature and content of the book, but there was no \"expert\" testimony that the book was \"utterly without redeeming social importance.\" The trial court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","3":"14"}},{"t":"case","label":"Knox v. Service Employees International Union, Local 1000","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Masterpiece Cakeshop, Ltd. v. Colorado Civil Rights Commission","cite":"138 S. Ct. 1719","y":2018,"id":"2017/16-111","sc":1,"op":8,"ar":8,"sum":"The Court held that the Colorado Civil Rights Commission's conduct in evaluating a cake shop owner's reasons for declining to make a wedding cake for a same-sex couple violated the Free Exercise Clause.","sumSrc":"Oyez","by":{"0":"passim","1":"40, 39","2":"passim","3":"9, 15"}},{"t":"case","label":"Mastrovincenzo v. City of New York","cite":"435 F.3d 78","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/435/78/","by":{"0":"18"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"35, 39","3":"20"}},{"t":"case","label":"McCullen v. Coakley","cite":"573 U.S. 464","y":2014,"id":"2013/12-1168","sc":1,"op":1,"sum":"The Court ruled that the Massachusetts legislature violated the freedom of speech protections of the First Amendment when it created a 35-foot buffer around the entrances, exits and driveways of abortion clinics where political activity was prohibited.","sumSrc":"Oyez","by":{"0":"13, 47, 49","2":"30"}},{"t":"case","label":"Miami Herald Publishing Company v. Tornillo","cite":"418 U.S. 241","y":1974,"id":"1973/73-797","sc":1,"op":1,"ar":2,"sum":"The Court reversed the Supreme Court of Florida and held that Florida's \"right to reply\" statute violated the freedom of press found in the First Amendment. In an opinion written by Chief Justice Warren E. Burger, the Court recognized the risks posed to the \"true marketplace of ideas\" by media consolidation and barriers to entry in the newspaper industry.","sumSrc":"Oyez","by":{"0":"passim","1":"19","2":"30","3":"12, 20"}},{"t":"case","label":"National Institute of Family & Life Advocates v. Becerra","cite":"138 S. Ct. 2361","y":2018,"id":"2017/16-1140","sc":1,"op":3,"sum":"The Court decided that pro-life pregnancy center petitioners were likely to succeed on their claim that the California Reproductive Freedom, Accountability, Comprehensive Care, and Transparency Act violated the First Amendment.","sumSrc":"Oyez","by":{"0":"17, 32, 33, 43","2":"10","3":"1, 10"}},{"t":"case","label":"New York State Club Association v. City of New York","cite":"487 U.S. 1","y":1988,"id":"1987/86-1836","sc":1,"sum":"The Court examined the clubs subjected to anti-discrimination laws closely and found \"no evidence of any club, let alone a substantial number of clubs, for whom the Law impairs the ability to associate or to advocate public or private viewpoints.\" In addition, many of the clubs showed characteristics of a public nature. Often strangers attended club functions, partook in meals, and made financial contributions.","sumSrc":"Oyez","by":{"0":"24","1":"14","2":"26","3":"16"}},{"t":"case","label":"New York Times Company v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Obergefell v. Hodges","cite":"576 U.S. 644","y":2015,"id":"2014/14-556","sc":1,"op":3,"ar":6,"sum":"The Court held that the Fourteenth Amendment requires states to license and recognize same-sex marriage.","sumSrc":"Oyez","by":{"0":"42, 48","2":"27","3":"21"}},{"t":"case","label":"Pacific Gas & Electric Company v. Public Utilities Commission of California","cite":"475 U.S. 1","y":1986,"id":"1985/84-1044","sc":1,"ar":1,"sum":"The Commission's decision must be vacated. Remanded. JUSTICE POWELL, joined by THE CHIEF JUSTICE, JUSTICE BRENNAN, and JUSTICE O'CONNOR, concluded:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"19"}},{"t":"case","label":"Pittsburgh Press Company v. Pittsburgh Commission on Human Relations","cite":"413 U.S. 376","y":1973,"id":"1972/72-419","sc":1,"op":2,"sum":"The Court held that an ordinance that forbids newspapers to advertise employment opportunities in gender-designated columns does not violate the freedom of press guaranteed by the First Amendment.","sumSrc":"Oyez","by":{"0":"34","1":"44, 45","2":"34"}},{"t":"case","label":"PruneYard Shopping Center v. Robins","cite":"447 U.S. 74","y":1980,"id":"1979/79-289","sc":1,"sum":"Since the California Constitution protected \"speech and petitioning, reasonably exercised, in shopping centers even when the shopping centers are privately owned,\" PruneYard could not prevent the students from soliciting on its property. The Court argued that it was within California's power to guarantee this expansive free speech right since it did not unreasonably intrude on the rights of private property owners.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Ramirez v. Collier","cite":"142 S. Ct. 1264","y":2022,"id":"2021/21-5592","sc":1,"sum":"Petitioner Ramirez is likely to succeed on his claims under the Religious Land Use and Institutionalized Persons Act of 2000 because Texas’s restrictions on religious touch and audible prayer in the execution chamber burden religious exercise and are not the least restrictive means of furthering the State’s compelling interests.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47","3":"21"}},{"t":"case","label":"Reed v. Town of Gilbert","cite":"576 U.S. 155","y":2015,"id":"2014/13-502","sc":1,"sum":"The Court decided that extra restrictions placed on signs describing the location of nonprofit events do not survive strict scrutiny and are therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"31, 34, 36","3":"18"}},{"t":"case","label":"Reno v. ACLU","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"op":1,"ar":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"19, 47"}},{"t":"case","label":"Riley v. National Federation of the Blind of North Carolina, Inc.","cite":"487 U.S. 781","y":1988,"id":"1987/87-328","sc":1,"op":2,"sum":"The North Carolina Charitable Solicitations Act defines the prima facie \"reasonable fee\" that a professional fundraiser may charge according to a three-tiered schedule. A fee up to 20% of receipts collected is deemed reasonable. A fee between 20% and 35% is deemed unreasonable upon a showing that the solicitation at issue did not involve the \"dissemination of information, discussion, or advocacy relating to public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 32, 36, 46"}},{"t":"case","label":"Roberts v. United States Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"op":11,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"0":"21, 24, 43","1":"14, 37, 43","2":"passim"}},{"t":"case","label":"Rosenberger v. Rector & Visitors of University of Virginia","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"op":18,"sum":"The Court, in a 5-to-4 opinion, held that the University's denial of funding to Rosenberger, due to the content of his message, imposed a financial burden on his speech and amounted to viewpoint discrimination. The Court noted that no matter how scarce University publication funding may be, if it chooses to promote speech at all, it must promote all forms of it equally.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"op":18,"ar":5,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"15, 18, 20, 21, 23, 29, 44, 45","2":"passim","3":"7, 8, 10"}},{"t":"case","label":"Runyon v. McCrary","cite":"427 U.S. 160","y":1976,"id":"1975/75-62","sc":1,"op":7,"ar":1,"sum":"The Court held that Section 1981 prohibited the racially discriminatory policies of the schools.","sumSrc":"Oyez","by":{"0":"18","1":"14, 38","3":"7"}},{"t":"case","label":"SBA List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"0":"10","3":"5"}},{"t":"case","label":"Simon & Schuster, Inc. v. Members of the New York State Crime Victims Board","cite":"502 U.S. 105","y":1991,"id":"1991/90-1059","sc":1,"op":1,"sum":"The Court concluded that \"New York has singled out speech on a particular subject for a financial burden that it places on no other speech and no other income.\" This discrimination could only be justified if the state could show \"that its regulation is necessary to serve a compelling state interest and is narrowly drawn to achieve that end\" (Arkansas Writers' Project, Inc. v. Ragland, 481 U.S. 221, 231 (1987)).","sumSrc":"Oyez","by":{"0":"20, 43, 44"}},{"t":"case","label":"Snyder v. Phelps","cite":"562 U.S. 443","y":2011,"id":"2010/09-751","sc":1,"op":2,"sum":"The Court held that the Westboro Baptist Church was protected under the First Amendment while picketing a military funeral.","sumSrc":"Oyez","by":{"0":"35, 42"}},{"t":"case","label":"Sorrell v. IMS Health Inc.","cite":"564 U.S. 552","y":2011,"id":"2010/10-779","sc":1,"op":4,"sum":"The Court held that a Vermont statute banning the sale, transmission or use of prescription drug user data violated protected speech of the pharmaceutical research companies, manufacturers and others who use that data.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Spence v. Washington","cite":"418 U.S. 405","y":1974,"id":"1973/72-1690","sc":1,"ar":1,"sum":"The Supreme Court held that that statute, as applied, violated the First Amendment right to free speech. Justice William O. Douglas concurred, writing that Spence’s display was symbolic speech entitled to constitutional protection. Justice Harry A. Blackmun concurred in the result.","sumSrc":"Oyez","by":{"0":"23","1":"21"}},{"t":"case","label":"Telecom Association v. FCC","cite":"855 F.3d 381","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/855/381/","by":{"0":"46"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"sum":"The Court held that burning the American Flag is protected free speech under the First Amendment.","sumSrc":"Oyez","by":{"0":"30","1":"21, 25, 27","2":"10, 11"}},{"t":"case","label":"Torcaso v. Watkins","cite":"367 U.S. 488","y":1961,"id":"1960/373","sc":1,"sum":"The Court held that such a requirement places the state of Maryland firmly on the side of those people who believe in God and are willing to state their belief. With this requirement, Maryland effectively aids religions that profess a belief in God at the expense of any other form of belief or disbelief. The First Amendment expressly prohibits a state from taking this position.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Turner Broadcasting System, Inc. v. FCC","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"sum":"The Court held that the must-carry provisions were content neutral, thus not a violation of the First Amendment. The rules were not determined by the programming content, but by broadcast method. The rules promote fair competition in television programming.","sumSrc":"Oyez","by":{"0":"31, 44","2":"11"}},{"t":"case","label":"United States v. E.I. du Pont de Nemours & Company","cite":"351 U.S. 377","y":1956,"id":"1955/5","sc":1,"sum":"In a civil action under § 4 of the Sherman Act, the Government charged that appellee had monopolized interstate commerce in cellophane in violation of § 2 of the Act. During the relevant period, appellee produced almost 75% of the cellophane sold in the United States; but cellophane constituted less than 20% of all flexible packaging materials sold in the United States. The trial court found that the relevant market …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"United States v. Playboy Entertainment Group, Inc.","cite":"529 U.S. 803","y":2000,"id":"1999/98-1682","sc":1,"sum":"The Court held that because the Federal Government failed to show that section 505 was the least restrictive means to further its interests, requiring cable television operators to fully scramble or limit time when sexually-oriented programming was transmitted violated the First Amendment's free speech guarantee.","sumSrc":"Oyez","by":{"0":"36, 38, 47, 49"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"op":3,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Vejo v. Portland Public Schools","cite":"204 F. Supp. 3d 1149","y":2016,"court":"D. Or.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/204/1149/","sum":"Interpreting Oregon law to conclude that a university program was too selective to qualify as a public accommodation.","sumSrc":"brief:0","by":{"0":"49"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"West Virginia State Board of Education v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"op":18,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"0":"passim","1":"19","2":"17","3":"12, 25"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"575 U.S. 433","y":2015,"id":"2014/13-1499","sc":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"op":1,"ar":1,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"0":"17, 23, 29, 40","1":"19","2":"17","3":"1"}},{"t":"case","label":"World Peace Movement v. Newspaper Agency Corp., Inc.","cite":"879 P.2d 253","y":1994,"court":"Utah","url":"https://www.courtlistener.com/c/P.2d/879/253/","by":{"0":"48","3":"16"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"reg","label":"29 C.F.R. § 1604.2","url":"https://www.ecfr.gov/current/title-29/section-1604.2","by":{"0":"48"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"1, 16","2":"passim"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"1"}},{"t":"case","label":"44 Liquormart, Inc. v. Rhode Island","cite":"517 U.S. 484","y":1996,"id":"1995/94-1140","sc":1,"op":1,"sum":"In a fractious opinion for a unanimous Court, Justice Stevens found Rhode Island's statutory ban on liquor price advertising to be an unconstitutional infringement of the liquor sellers' First Amendment right to freedom of speech.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Adickes v. S.H. Kress & Co.","cite":"398 U.S. 144","y":1970,"id":"1969/79","sc":1,"sum":"Petitioner is a white school teacher who was refused service in respondent's lunchroom when she was accompanied by six Negro students, and who was arrested for vagrancy by the Hattiesburg, Mississippi, police when she left respondent's premises. She filed a complaint in the Federal District Court to recover damages alleging deprivation of her right under the Equal Protection Clause not to be discriminated against on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Alfred L. Snapp & Son, Inc. v. Puerto Rico ex rel. Barez","cite":"458 U.S. 592","y":1982,"id":"1981/80-1305","sc":1,"sum":"Puerto Rico has parens patriae standing to maintain this suit. Pp. 600-610. ALFRED L. SNAPP & SON, INC. v. PUERTO RICO (a) In order to maintain a parens patriaeaction, a State must articulate an interest apart from the interests of particular private parties, that is, the State must be more than a nominal party. The State must express a \"quasi-sovereign\" interest, such as its interest in the health and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Allnutt v. Inglis","cite":"104 Eng. Rep. 206","y":1810,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./104/206/","by":{"1":"36"}},{"t":"case","label":"Babbitt v. United Farm Workers Nat. Union","cite":"442 U.S. 289","y":1979,"id":"1978/78-225","sc":1,"sum":"Appellees (a farmworkers' union, a union agent, farmworkers, and a union supporter) brought suit in Federal District Court in Arizona seeking a declaration of the unconstitutionality of various provisions of Arizona's farm labor statute, as well as of the entire statute, and an injunction against \"its enforcement. A three-judge court ruled unconstitutional on various grounds the provisions (1) specifying procedures …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Bd. of Dirs. of Rotary Int’l v. Rotary Club of Duarte","cite":"481 U.S. 537","y":1987,"id":"1986/86-421","sc":1,"op":1,"sum":"Considering the size, purpose, selectivity, and exclusivity of Rotary's membership, the Court found that the relationship among the club's members was not of the intimate or private variety which warrants First Amendment protection.","sumSrc":"Oyez","by":{"1":"14, 37","2":"26"}},{"t":"case","label":"Bell v. Maryland","cite":"378 U.S. 226","y":1964,"id":"1963/12","sc":1,"sum":"The Court held that the defendants' convictions could not be upheld, since intervening Maryland state law enacted during the Supreme Court's review of the case rendered their actions legal.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"op":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Bostock v. Clayton Cnty., Ga.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"1":"16","2":"20"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"1":"38","2":"31"}},{"t":"case","label":"Cent. Hudson Gas & Elec. Corp. v. Pub. Serv. Comm’n","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"op":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Chicago, St. L. & P. R. Co. v. Holdridge","cite":"20 N.E. 837","y":1889,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E./20/837/","by":{"1":"37"}},{"t":"case","label":"Church of the Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"op":1,"ar":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Clark v. Cmty. for Creative Non-Violence","cite":"468 U.S. 288","y":1984,"id":"1983/82-1998","sc":1,"op":8,"sum":"In a 7-to-2 decision, the Court held that the regulations did not violate the First Amendment. The Court noted that expression is subject to reasonable time, place, and manner restrictions, and that the manner of the protest was at odds with the government's interest in maintaining the condition of the parks.","sumSrc":"Oyez","by":{"1":"26","3":"14"}},{"t":"case","label":"Donnell v. State","cite":"48 Miss. 661","y":1873,"url":"https://www.courtlistener.com/c/Miss./48/661/","by":{"1":"4"}},{"t":"case","label":"Emp. Division v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Ferguson v. Gies","cite":"46 N.W. 718","y":1890,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./46/718/","op":2,"by":{"1":"4"}},{"t":"case","label":"Giboney v. Empire Storage & Ice Co.","cite":"336 U.S. 490","y":1949,"id":"scdb/1948-056","sc":1,"sum":"The state law, as construed and applied in this case, does not violate the Federal Constitution, and the judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Heart of Atlanta Motel, Inc. v. United States","cite":"379 U.S. 241","y":1964,"id":"1964/515","sc":1,"op":6,"sum":"The Court found that hotels did not have the right to discriminate against black guests under Title II of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"14, 38","2":"11"}},{"t":"case","label":"Hishon v. King & Spalding","cite":"467 U.S. 69","y":1984,"id":"1983/82-940","sc":1,"op":6,"sum":"The Court held that Title VII makes it illegal for an employer to discriminate against any employee on the basis of their sex. In this case, the Court held that the promise of equal consideration for partnership that went along with Hishon’s employment was contractual in nature and subject to the regulations of Title VII.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Jones v. Alfred H. Mayer, Co.","cite":"392 U.S. 409","y":1968,"id":"1967/645","sc":1,"op":1,"sum":"The Court sided with Jones and held that Section 1982 of the congressional act was intended to prohibit all discrimination against blacks in the sale and rental of property, including governmental and private discrimination.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Lane v. Cotton","cite":"88 Eng. Rep. 1458","y":1701,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./88/1458/","op":5,"by":{"1":"3"}},{"t":"case","label":"Messenger v. State","cite":"41 N.W. 638","y":1889,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./41/638/","by":{"1":"4"}},{"t":"case","label":"Nebbia v. People of New York","cite":"291 U.S. 502","y":1934,"id":"1900-1940/291us502","sc":1,"sum":"The Court held that a New York regulation establishing a board to set a minimum retail price of milk did not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"27, 40"}},{"t":"case","label":"Newman v. Piggie Park Enters., Inc.","cite":"390 U.S. 400","y":1968,"id":"1967/339","sc":1,"op":3,"sum":"One who succeeds in obtaining an injunction under Title II of the Civil Rights Act of 1964 should ordinarily recover an attorney's fee under § 204 (b) unless special circumstances would render such an award unjust, and should not be limited, as the Court of Appeals held, to an award of counsel fees only if the defenses advanced were \"for purposes of delay and not in good faith.\" 377 F. 2d 433, modified and affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14","2":"11"}},{"t":"case","label":"People v. King","cite":"18 N.E. 245","y":1888,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./18/245/","by":{"1":"4"}},{"t":"case","label":"Phillips v. Martin Marietta Corp.","cite":"400 U.S. 542","y":1971,"id":"1970/73","sc":1,"sum":"A case in which that Court held that, in the absence of evidence that having preschool-age children is demonstrably more relevant to female job performance than to male job performance, a refusal to hire women with preschool-age children violates the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Pub. Affairs Assocs. v. Rickover","cite":"369 U.S. 111","y":1962,"id":"1961/36","sc":1,"sum":"In this action under the Declaratory Judgment. Act for a determination of the rights of Vice Admiral Rickover with respect to his speeches, the record, consisting mainly of a sketchy agreed statement of facts, is not a satisfactory basis for a discretionary grant of declaratory relief relating to claims to intellectual property arising out of public employment. Pp. 111-114. 109 U. S. App. D. C. 128, 284 F. 2d 262, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Romer v. Evans","cite":"517 U.S. 620","y":1996,"id":"1995/94-1039","sc":1,"op":2,"sum":"The Court found a Colorado amendment that banned protection from discrimination based on sexual orientation violated the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Sauvinet v. Walker","cite":"27 La. Ann. 14","y":1875,"url":"https://www.courtlistener.com/c/La.%20Ann./27/14/","by":{"1":"4"}},{"t":"case","label":"Tandon v. Newsom","cite":"141 S. Ct. 1294","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1294/","sc":1,"sum":"Noting the Court’s “nuanced” resolution of such First Amendment conflicts.","sumSrc":"brief:1","by":{"1":"30, 41"}},{"t":"case","label":"Texas v. United States","cite":"523 U.S. 296","y":1998,"id":"1997/97-29","sc":1,"sum":"The Court held that Texas's claim is not ripe for adjudication.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"United States v. Albertini","cite":"472 U.S. 675","y":1985,"id":"1984/83-1624","sc":1,"op":1,"sum":"Title 18 U. S. C. § 1382 makes it unlawful to reenter a military base after having been \"ordered not to reenter by any officer in command or charge thereof.\" In 1972, respondent received from the commanding officer of Hickam Air Force Base in Hawaii a letter (bar letter) forbidding him to reenter the base without written permission from the commanding officer or his designate. The letter was issued after respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 39","2":"10, 11"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1967,"id":"1967/232","sc":1,"op":4,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"1":"21, 25, 26","2":"6, 10","3":"17"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"op":1,"sum":"The Court upheld the ordinance, giving broad deference to the government's interest in maintaining order. As long as \"the means chosen are not substantially broader than necessary to achieve the government's interest,\" a regulation will not be invalidated because a court concludes that the government's interest \"could be adequately served by some less-speech-restrictive alternative.\".","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Wisconsin v. Mitchell","cite":"508 U.S. 476","y":1993,"id":"1992/92-515","sc":1,"sum":"The Court found that the Wisconsin statute paralleled antidiscrimination laws which had been found to comply with the First Amendment. It also determined that the consequences for the victim and the community tended to be more severe, when the victim of a crime was chosen on account of his or her race.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Br. for Scholars of Behavioral Science and Economics as Amici Curiae Supporting Respondents, 303 Creative LLC v. Elenis","cite":"6 F.4th 1160","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/1160/","op":15,"by":{"1":"43"}},{"t":"case","label":"Daniel v. Paul","cite":"395 U.S. 298","y":1969,"id":"1968/488","sc":1,"op":1,"sum":"Lake Nixon Club is an amusement place owned by respondent and his wife, located 12 miles from Little Rock, Ark. It has recreation facilities, including swimming, boating, and dancing, and a snack bar serving four food items, at least three of which contain ingredients coming from outside the State. The Club leases 15 paddle boats on a royalty basis from an Oklahoma company (from which it purchased one boat) and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2, 33"}},{"t":"case","label":"Doe v. Reed","cite":"561 U.S. 186","y":2010,"id":"2009/09-559","sc":1,"sum":"The Court held that requiring the disclosure of the names of individuals who sign a referendum petition does not violate the signers' First Amendment rights to protection of political speech.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"R. A. V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"usc","label":"42 U.S.C. § 12181","url":"https://www.law.cornell.edu/uscode/text/42/12181","stext":{"head":"§12181. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Commerce"],[1,"The term \"commerce\" means travel, trade, traffic, commerce, transportation, or communication—"],[2,"(A) among the several States;"],[2,"(B) between any foreign country or any territory or possession and any State; or"],[2,"(C) between points in the same State but through another State or foreign country."],[0,"(2) Commercial facilities"],[1,"The term \"commercial facilities\" means facilities—"],[2,"(A) that are intended for nonresidential use; and"],[2,"(B) whose operations will affect commerce."],[1,"Such term shall not include railroad locomotives, railroad freight cars, railroad cabooses, railroad cars described in section 12162 of this title or covered under this subchapter, railroad rights-of-way, or facilities that are covered or expressly exempted from coverage under the Fair Housing Act of 1968 1 (42 U.S.C. 3601 et seq.)."],[0,"(3) Demand responsive system"],[1,"The term \"demand responsive system\" means any system of providing transportation of individuals by a vehicle, other than a system which is a fixed route system."],[0,"(4) Fixed route system"],[1,"The term \"fixed route system\" means a system of providing transportation of individuals (other than by aircraft) on which a vehicle is operated along a prescribed route according to a fixed schedule."],[0,"(5) Over-the-road bus"],[1,"The term \"over-the-road bus\" means a bus characterized by an elevated passenger deck located over a baggage compartment."],[0,"(6) Private entity"],[1,"The term \"private entity\" means any entity other than a public entity (as defined in section 12131(1) of this title)."],[0,"(7) Public accommodation"],[1,"The following private entities are considered public accommodations for purposes of this subchapter, if the operations of such entities affect commerce—"],[2,"(A) an inn, hotel, motel, or other place of lodging, except for an establishment located within a building that contains not more than five rooms for rent or hire and that is actually occupied by the proprietor of such establishment as the residence of such proprietor;"],[2,"(B) a restaurant, bar, or other establishment serving food or drink;"],[2,"(C) a motion picture house, theater, concert hall, stadium, or other place of exhibition or entertainment;"],[2,"(D) an auditorium, convention center, lecture hall, or other place of public gathering;"],[2,"(E) a bakery, grocery store, clothing store, hardware store, shopping center, or other sales or rental establishment;"],[2,"(F) a laundromat, dry-cleaner, bank, barber shop, beauty shop, travel service, shoe repair service, funeral parlor, gas station, office of an accountant or lawyer, pharmacy, insurance office, professional office of a health care provider, hospital, or other service establishment;"],[2,"(G) a terminal, depot, or other station used for specified public transportation;"],[2,"(H) a museum, library, gallery, or other place of public display or collection;"],[2,"(I) a park, zoo, amusement park, or other place of recreation;"],[2,"(J) a nursery, elementary, secondary, undergraduate, or postgraduate private school, or other place of education;"],[2,"(K) a day care center, senior citizen center, homeless shelter, food bank, adoption agency, or other social service center establishment; and"],[2,"(L) a gymnasium, health spa, bowling alley, golf course, or other place of exercise or recreation."],[0,"(8) Rail and railroad"],[1,"The terms \"rail\" and \"railroad\" have the meaning given the term \"railroad\" in section 20102(1) 1 of title 49."],[0,"(9) Readily achievable"],[1,"The term \"readily achievable\" means easily accomplishable and able to be carried out without much difficulty or expense. In determining whether an action is readily achievable, factors to be considered include—"],[2,"(A) the nature and cost of the action needed under this chapter;"],[2,"(B) the overall financial resources of the facility or facilities involved in the action; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such action upon the operation of the facility;"],[2,"(C) the overall financial resources of the covered entity; the overall size of the business of a covered entity with respect to the number of its employees; the number, type, and location of its facilities; and"],[2,"(D) the type of operation or operations of the covered entity, including the composition, structure, and functions of the workforce of such entity; the geographic separateness, administrative or fiscal relationship of the facility or facilities in question to the covered entity."],[0,"(10) Specified public transportation"],[1,"The term \"specified public transportation\" means transportation by bus, rail, or any other conveyance (other than by aircraft) that provides the general public with general or special service (including charter service) on a regular and continuing basis."],[0,"(11) Vehicle"],[1,"The term \"vehicle\" does not include a rail passenger car, railroad locomotive, railroad freight car, railroad caboose, or a railroad car described in section 12162 of this title or covered under this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12181?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12181. Definitions","tname":"The Public Health and Welfare","by":{"2":"1"}},{"t":"usc","label":"42 U.S.C. § 2000","url":"https://www.law.cornell.edu/uscode/text/42/2000","by":{"2":"1"}},{"t":"usc","label":"42 U.S.C. § 2000a","url":"https://www.law.cornell.edu/uscode/text/42/2000a","stext":{"head":"§2000a. Prohibition against discrimination or segregation in places of public accommodation","paras":[[0,"(a) Equal access"],[0,"All persons shall be entitled to the full and equal enjoyment of the goods, services, facilities, privileges, advantages, and accommodations of any place of public accommodation, as defined in this section, without discrimination or segregation on the ground of race, color, religion, or national origin."],[0,"(b) Establishments affecting interstate commerce or supported in their activities by State action as places of public accommodation; lodgings; facilities principally engaged in selling food for consumption on the premises; gasoline stations; places of exhibition or entertainment; other covered establishments"],[0,"Each of the following establishments which serves the public is a place of public accommodation within the meaning of this subchapter if its operations affect commerce, or if discrimination or segregation by it is supported by State action:"],[1,"(1) any inn, hotel, motel, or other establishment which provides lodging to transient guests, other than an establishment located within a building which contains not more than five rooms for rent or hire and which is actually occupied by the proprietor of such establishment as his residence;"],[1,"(2) any restaurant, cafeteria, lunchroom, lunch counter, soda fountain, or other facility principally engaged in selling food for consumption on the premises, including, but not limited to, any such facility located on the premises of any retail establishment; or any gasoline station;"],[1,"(3) any motion picture house, theater, concert hall, sports arena, stadium or other place of exhibition or entertainment; and"],[1,"(4) any establishment (A)(i) which is physically located within the premises of any establishment otherwise covered by this subsection, or (ii) within the premises of which is physically located any such covered establishment, and (B) which holds itself out as serving patrons of such covered establishment."],[0,"(c) Operations affecting commerce; criteria; \"commerce\" defined"],[0,"The operations of an establishment affect commerce within the meaning of this subchapter if (1) it is one of the establishments described in paragraph (1) of subsection (b); (2) in the case of an establishment described in paragraph (2) of subsection (b), it serves or offers to serve interstate travelers or a substantial portion of the food which it serves, or gasoline or other products which it sells, has moved in commerce; (3) in the case of an establishment described in paragraph (3) of subsection (b), it customarily presents films, performances, athletic teams, exhibitions, or other sources of entertainment which move in commerce; and (4) in the case of an establishment described in paragraph (4) of subsection (b), it is physically located within the premises of, or there is physically located within its premises, an establishment the operations of which affect commerce within the meaning of this subsection. For purposes of this section, \"commerce\" means travel, trade, traffic, commerce, transportation, or communication among the several States, or between the District of Columbia and any State, or between any foreign country or any territory or possession and any State or the District of Columbia, or between points in the same State but through any other State or the District of Columbia or a foreign country."],[0,"(d) Support by State action"],[0,"Discrimination or segregation by an establishment is supported by State action within the meaning of this subchapter if such discrimination or segregation (1) is carried on under color of any law, statute, ordinance, or regulation; or (2) is carried on under color of any custom or usage required or enforced by officials of the State or political subdivision thereof; or (3) is required by action of the State or political subdivision thereof."],[0,"(e) Private establishments"],[0,"The provisions of this subchapter shall not apply to a private club or other establishment not in fact open to the public, except to the extent that the facilities of such establishment are made available to the customers or patrons of an establishment within the scope of subsection (b)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000a?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2000a. Prohibition against discrimination or segregation in places of public accommodation","tname":"The Public Health and Welfare","by":{"2":"1"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"2":"30, 31"}},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(b)"],"by":{"2":"34"}},{"t":"usc","label":"42 U.S.C. § 3604","url":"https://www.law.cornell.edu/uscode/text/42/3604","subs":["(c)"],"by":{"2":"34"}},{"t":"case","label":"Chelsey Nelson Photography, LLC v. Louisville/Jefferson County Metro Government","cite":"2022 WL 3972873","y":2022,"court":"W.D. Ky. Aug. 30","sum":"Finding application of similar law to be content based.","sumSrc":"brief:3","by":{"3":"18"}},{"t":"case","label":"FEC v. Wisconsin Right to Life","cite":"551 U.S. 449","y":2007,"id":"2006/06-969","sc":1,"op":1,"sum":"Observing that “a speaker's motivation is entirely irrelevant” (internal quotation marks omitted).","sumSrc":"opinion","by":{"3":"5"}},{"t":"case","label":"Hess v. Indiana","cite":"414 U.S. 105","y":1973,"id":"1973/73-5290","sc":1,"sum":"Appellant's language didnot fall within any, of the \"narrowly limited classes of speech\" that the States may punish without -violating the First and Fourteenth Amendments, land since-the evidence showed that the. words he used were not directed to any person or group and.there was no evidence that they were intended and likely to proiiuce imminent disorder, application of the statute to appellant violated his rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Holt v. Hobbs","cite":"574 U.S. 352","y":2015,"id":"2014/13-6827","sc":1,"op":4,"sum":"The Court held that the Department of Corrections' grooming policy violated an inmate's right to religious exercise.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"New York State Rifle & Pistol Association v. Bruen","cite":"142 S. Ct. 2111","y":2022,"id":"2021/20-843","sc":1,"sum":"New York’s proper-cause requirement for obtaining an unrestricted license to carry a concealed firearm violates the Fourteenth Amendment in that it prevents law-abiding citizens with ordinary self-defense needs from exercising their Second Amendment right to keep and bear arms.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"22, 23, 24"}},{"t":"case","label":"Parents Involved in Community Schools v. Seattle School District No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"sum":"By a 5-4 vote, the Court applied a \"strict scrutiny\" framework and found Jefferson County's enrollment plan unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"Shurtleff v. City of Boston","cite":"142 S. Ct. 1583","y":2022,"id":"2021/20-1800","sc":1,"op":1,"sum":"Because Boston’s flag-raising program did not constitute government speech, Boston’s refusal to let petitioners fly their flag violated the Free Speech Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"Thomas v. Union Carbide Agricultural Products Company","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) requires manufacturers of pesticides, as a precondition for registering a pesticide, to submit research data to the Environmental Protection Agency (EPA) concerning the product's health, safety, and environmental effects, and authorizes EPA to use previously submitted data in considering an application for registration of a similar product by another …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Turner Broadcasting System v. FCC","cite":"520 U.S. 180","y":1997,"id":"1996/95-992","sc":1,"sum":"In a 5-to-4 decision, the Court held that Congress \"has an independent interest in preserving a multiplicity of broadcasters.\" The outcome supported Congress's right to judge what approach would best insure a competitive communications marketplace.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"United States v. United Foods, Inc.","cite":"533 U.S. 405","y":2001,"id":"2000/00-276","sc":1,"sum":"The Court held that the assessment requirement violates the First Amendment.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Virginia v. American Booksellers Association","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}}]};